# Generated by hand on 2026-10-22 - follow-up to 0070, which stored
# push_notification_urls in plaintext (webhook URLs/bot tokens are live
# credentials, same sensitivity class as the OAuth tokens that already
# get encrypted via tracker/crypto.py). Encrypts any value already saved
# in the brief window since 0070 shipped, rather than assuming the
# column is still empty everywhere.

from django.db import migrations, models


def encrypt_existing_urls(apps, schema_editor):
    from tracker import crypto

    Profile = apps.get_model("tracker", "Profile")
    for profile in Profile.objects.exclude(push_notification_urls="").only(
        "id", "push_notification_urls"
    ):
        profile.encrypted_push_notification_urls = crypto.encrypt(profile.push_notification_urls)
        profile.save(update_fields=["encrypted_push_notification_urls"])


def decrypt_existing_urls(apps, schema_editor):
    from tracker import crypto

    Profile = apps.get_model("tracker", "Profile")
    for profile in Profile.objects.exclude(encrypted_push_notification_urls="").only(
        "id", "encrypted_push_notification_urls"
    ):
        profile.push_notification_urls = crypto.decrypt(profile.encrypted_push_notification_urls)
        profile.save(update_fields=["push_notification_urls"])


class Migration(migrations.Migration):

    dependencies = [
        ('tracker', '0070_profile_push_notification_urls_and_more'),
    ]

    operations = [
        migrations.AddField(
            model_name='profile',
            name='encrypted_push_notification_urls',
            field=models.TextField(blank=True, default=''),
        ),
        migrations.RunPython(encrypt_existing_urls, decrypt_existing_urls),
        migrations.RemoveField(
            model_name='profile',
            name='push_notification_urls',
        ),
    ]
